import { event } from "@useamplio/amplio";
import { z } from "zod";
// amplio:plugin-imports

export const HttpRequest = event({
  id: "http.request",
  version: 1,
  schema: z.object({
    request_id: z.string(),
    http: z.object({
      method: z.string(),
      route: z.string().optional(),
      status: z.number().int().optional(),
    }),
  }),
  tree: {
    // amplio:plugins
  },
});

export function resolveRequestId(value: unknown): string {
  if (typeof value === "string" && /^[A-Za-z0-9_-]{1,128}$/.test(value)) {
    return value;
  }
  return crypto.randomUUID();
}

import "../runtime.js";

import type { Context, MiddlewareHandler, Next } from "hono";
import { HttpRequest, resolveRequestId } from "../events/http-request.js";

const handleRequest = HttpRequest.handle(
  async (context: Context, next: Next) => {
    await next();
  },
  {
    input: ({ args: [context] }) => ({
      request_id: resolveRequestId(context.req.header("x-request-id")),
      http: { method: context.req.method },
    }),
    result: ({ args: [context] }) => ({
      http: {
        route: context.req.routePath || undefined,
        status: context.res.status,
      },
    }),
    success: ({ args: [context] }) => context.res.status < 400,
    error: ({ args: [context] }) => ({
      http: {
        route: context.req.routePath || undefined,
      },
    }),
  },
);

/** Hono boundary Plugin: application handlers remain ordinary Hono handlers. */
export function HonoPlugin(): MiddlewareHandler {
  return handleRequest;
}

import "../runtime.js";

import { openEvent, type EventScope } from "@useamplio/amplio/plugin";
import type { ErrorRequestHandler, RequestHandler } from "express";
import { HttpRequest, resolveRequestId } from "../events/http-request.js";

interface PendingRequest {
  readonly scope: EventScope<typeof HttpRequest>;
  error?: unknown;
  settled: boolean;
}

/**
 * Put the boundary first by spreading every returned route layer.
 * All supplied middleware and the final response lifecycle stay in one Event.
 */
export function withAmplioRoute(
  route: string,
  ...handlers: RequestHandler[]
): Array<RequestHandler | ErrorRequestHandler> {
  const pending = new WeakMap<object, PendingRequest>();

  const boundary: RequestHandler = (request, response, next) => {
    const scope = openEvent(HttpRequest, {
      request_id: resolveRequestId(request.get("x-request-id")),
      http: { method: request.method, route },
    });
    const state: PendingRequest = { scope, settled: false };
    pending.set(request, state);

    const settle = (closedEarly: boolean) => {
      if (state.settled) return;
      state.settled = true;
      response.off("finish", onFinish);
      response.off("close", onClose);
      pending.delete(request);
      const output = {
        http: { route, status: response.statusCode },
      };
      if (state.error !== undefined) {
        scope.fail(state.error, output);
      } else if (closedEarly && !response.writableFinished) {
        scope.update(output);
        scope.cancel("response_closed");
      } else {
        scope.finish(output, { success: response.statusCode < 400 });
      }
    };
    const onFinish = scope.bind(() => settle(false));
    const onClose = scope.bind(() => settle(true));
    response.once("finish", onFinish);
    response.once("close", onClose);

    scope.run(() => {
      try {
        next();
      } catch (error) {
        state.error = error;
        next(error);
      }
    });
    if (response.writableFinished || response.destroyed) {
      settle(response.destroyed && !response.writableFinished);
    }
  };

  const captureError: ErrorRequestHandler = (
    error,
    request,
    _response,
    next,
  ) => {
    const state = pending.get(request);
    if (state && error !== "route" && error !== "router") {
      state.error = error;
    }
    next(error);
  };

  return [boundary, ...handlers, captureError];
}

import "../runtime.js";

import { openEvent, type EventScope } from "@useamplio/amplio/plugin";
import type { FastifyError, FastifyPluginAsync, FastifyRequest } from "fastify";
import { HttpRequest, resolveRequestId } from "../events/http-request.js";

interface PendingRequest {
  readonly scope: EventScope<typeof HttpRequest>;
  error?: FastifyError;
}

/** Register once before routes; ordinary Fastify handlers remain untouched. */
const implementation: FastifyPluginAsync = async (app) => {
  const pending = new WeakMap<FastifyRequest, PendingRequest>();

  app.addHook("onRequest", (request, _reply, done) => {
    const scope = openEvent(HttpRequest, {
      request_id: resolveRequestId(request.headers["x-request-id"]),
      http: { method: request.method },
    });
    pending.set(request, { scope });
    scope.run(done);
  });

  app.addHook("onError", (request, _reply, error, done) => {
    const state = pending.get(request);
    if (state) state.error = error;
    done();
  });

  app.addHook("onResponse", (request, reply, done) => {
    const state = pending.get(request);
    pending.delete(request);
    if (state) {
      const output = {
        http: {
          route: request.routeOptions.url,
          status: reply.statusCode,
        },
      };
      if (state.error) state.scope.fail(state.error, output);
      else {
        state.scope.finish(output, { success: reply.statusCode < 400 });
      }
    }
    done();
  });

  app.addHook("onRequestAbort", (request, done) => {
    const state = pending.get(request);
    pending.delete(request);
    if (state) {
      state.scope.update({
        http: { route: request.routeOptions.url },
      });
      state.scope.cancel("request_aborted");
    }
    done();
  });
};

// Fastify uses this documented symbol to expose lifecycle hooks outside the
// registration scope, which is exactly what a composition-root Plugin needs.
Object.defineProperties(implementation, {
  [Symbol.for("skip-override")]: { value: true },
  [Symbol.for("fastify.display-name")]: { value: "amplio-fastify" },
});

export const FastifyPlugin = implementation;

import "../runtime.js";

import type { NextRequest } from "next/server";
import { HttpRequest, resolveRequestId } from "../events/http-request.js";

type NextHandler = (
  request: NextRequest,
  ...args: any[]
) => Response | Promise<Response>;

export function withAmplio<F extends NextHandler>(
  route: string,
  handler: F,
): F {
  return HttpRequest.handle(handler, {
    input: ({ args: [request] }) => ({
      request_id: resolveRequestId(request.headers.get("x-request-id")),
      http: {
        method: request.method,
        route,
      },
    }),
    result: ({ result }) => ({
      http: { status: result.status },
    }),
    success: ({ result }) => result.status < 400,
  });
}

import { event } from "@useamplio/amplio";
import { plugin } from "@useamplio/amplio/plugin";
import { z } from "zod";

type TrpcProcedureType = "query" | "mutation" | "subscription";
type TrpcFailure = { ok: false; error: unknown };

const TrpcProcedure = event({
  id: "trpc.procedure",
  version: 1,
  schema: z.object({
    path: z.string(),
    type: z.enum(["query", "mutation"]),
  }),
  timing: "duration",
  cardinality: { many: { max: 64 } },
});

function isFailure(value: unknown): value is TrpcFailure {
  try {
    return (
      typeof value === "object" &&
      value !== null &&
      "ok" in value &&
      value.ok === false &&
      "error" in value
    );
  } catch {
    return false;
  }
}

export const TrpcPlugin = plugin({
  id: "trpc",
  events: { procedures: TrpcProcedure },
  instrument({ events, begin }) {
    return function trpcMiddleware() {
      return <Result>(options: {
        path: string;
        type: TrpcProcedureType;
        next: () => Promise<Result>;
      }): Promise<Result> => {
        // The middleware promise only represents subscription setup, not the
        // stream's lifetime. Preserve it exactly rather than claiming false
        // duration or completion semantics.
        if (options.type === "subscription") return options.next();

        const observation = begin(events.procedures, {
          path: options.path,
          type: options.type,
        });
        return observation.run(async () => {
          try {
            const result = await options.next();
            if (isFailure(result)) observation.fail(result.error);
            else observation.end();
            return result;
          } catch (error) {
            observation.fail(error);
            throw error;
          }
        });
      };
    };
  },
});

import { event } from "@useamplio/amplio";
import { plugin } from "@useamplio/amplio/plugin";
import type { BetterAuthPlugin as NativeBetterAuthPlugin } from "better-auth";
import { createAuthMiddleware } from "better-auth/api";
import { z } from "zod";

const AuthSession = {
  mfa: z.boolean().optional(),
  user: z.object({ id: z.string() }),
};

const SignedInResult = z.object({
  method: z.enum(["password", "oauth", "magic_link", "sso"]),
  ...AuthSession,
});

const SignedUpResult = z.object({
  method: z.enum(["email", "oauth", "invite"]),
  ...AuthSession,
});

type SignInMethod = z.infer<typeof SignedInResult>["method"];
type SignUpMethod = z.infer<typeof SignedUpResult>["method"];
type NativeAfterHook = NonNullable<
  NonNullable<NativeBetterAuthPlugin["hooks"]>["after"]
>[number];
type MatcherContext = Parameters<NativeAfterHook["matcher"]>[0];
type MiddlewareContext = Parameters<
  Parameters<typeof createAuthMiddleware>[0]
>[0];

function pathOf(context: MatcherContext): string {
  return typeof context.path === "string" ? context.path : "";
}

function hasConfirmedSession(context: MatcherContext): boolean {
  const id = context.context?.newSession?.user.id;
  return typeof id === "string" && id.length > 0;
}

function isRegistration(context: MatcherContext): boolean {
  const returned = context.context?.returned;
  if (returned === null || typeof returned !== "object") {
    return false;
  }

  try {
    return (returned as { isRegister?: unknown }).isRegister === true;
  } catch {
    return false;
  }
}

function isOAuthCallback(context: MatcherContext): boolean {
  const path = pathOf(context);
  return path.startsWith("/callback/") || path.startsWith("/oauth2/callback/");
}

function isEmailSignUp(context: MatcherContext): boolean {
  return pathOf(context) === "/sign-up/email" && hasConfirmedSession(context);
}

function isOAuthSignUp(context: MatcherContext): boolean {
  return (
    isOAuthCallback(context) &&
    hasConfirmedSession(context) &&
    isRegistration(context)
  );
}

function isInvitationSignUp(context: MatcherContext): boolean {
  const path = pathOf(context);
  return (
    (path === "/organization/signup-with-invitation" ||
      path.endsWith("/signup-with-invitation")) &&
    hasConfirmedSession(context)
  );
}

function isPasswordSignIn(context: MatcherContext): boolean {
  return (
    ["/sign-in/email", "/sign-in/username", "/sign-in/phone-number"].includes(
      pathOf(context),
    ) && hasConfirmedSession(context)
  );
}

function isOAuthSignIn(context: MatcherContext): boolean {
  return (
    isOAuthCallback(context) &&
    hasConfirmedSession(context) &&
    !isRegistration(context)
  );
}

function isMagicLinkSignIn(context: MatcherContext): boolean {
  return (
    pathOf(context) === "/magic-link/verify" && hasConfirmedSession(context)
  );
}

function isSsoSignIn(context: MatcherContext): boolean {
  const path = pathOf(context);
  return (
    (path === "/sign-in/sso" ||
      path.startsWith("/sso/callback") ||
      path.startsWith("/sso/saml2/")) &&
    hasConfirmedSession(context)
  );
}

function isMfaSignIn(context: MatcherContext): boolean {
  return (
    [
      "/two-factor/verify-totp",
      "/two-factor/verify-otp",
      "/two-factor/verify-backup-code",
    ].includes(pathOf(context)) && hasConfirmedSession(context)
  );
}

function projectSession(context: MiddlewareContext, forceMfa = false) {
  const session = context.context.newSession;
  if (!session?.user.id) {
    return;
  }

  const configuredMfa = session.user.twoFactorEnabled;
  const mfa = forceMfa
    ? true
    : typeof configuredMfa === "boolean"
      ? configuredMfa
      : undefined;

  return {
    user: { id: session.user.id },
    ...(mfa === undefined ? {} : { mfa }),
  };
}

export const BetterAuthPlugin = plugin({
  id: "better-auth",
  events: {
    signed_in: event({
      id: "auth.signed_in",
      version: 1,
      schema: SignedInResult,
      timing: "instant",
      cardinality: "single",
    }),
    signed_up: event({
      id: "auth.signed_up",
      version: 1,
      schema: SignedUpResult,
      timing: "instant",
      cardinality: "single",
    }),
  },
  instrument({ events, record }) {
    const recordSignedIn = (
      method: SignInMethod,
      context: MiddlewareContext,
      forceMfa = false,
    ): void => {
      const session = projectSession(context, forceMfa);
      if (!session) {
        return;
      }
      record(events.signed_in, { method, ...session });
    };

    const recordSignedUp = (
      method: SignUpMethod,
      context: MiddlewareContext,
    ): void => {
      const session = projectSession(context);
      if (!session) {
        return;
      }
      record(events.signed_up, { method, ...session });
    };

    return function createBetterAuthAdapter(): NativeBetterAuthPlugin {
      return {
        id: "amplio",
        hooks: {
          after: [
            {
              matcher: isEmailSignUp,
              handler: createAuthMiddleware(async (context) => {
                recordSignedUp("email", context);
              }),
            },
            {
              matcher: isInvitationSignUp,
              handler: createAuthMiddleware(async (context) => {
                recordSignedUp("invite", context);
              }),
            },
            {
              matcher: isOAuthSignUp,
              handler: createAuthMiddleware(async (context) => {
                recordSignedUp("oauth", context);
              }),
            },
            {
              matcher: isPasswordSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("password", context);
              }),
            },
            {
              matcher: isOAuthSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("oauth", context);
              }),
            },
            {
              matcher: isMagicLinkSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("magic_link", context);
              }),
            },
            {
              matcher: isSsoSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("sso", context);
              }),
            },
            {
              matcher: isMfaSignIn,
              handler: createAuthMiddleware(async (context) => {
                recordSignedIn("password", context, true);
              }),
            },
          ],
        },
      };
    };
  },
});

