  MAX_AGGREGATE_COUNT,
] as const;

function positiveIntegerBucket(
  value: unknown,
  boundaries: readonly number[],
): number | undefined {
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0) {
    return undefined;
  }
  return boundaries.find((boundary) => value <= boundary);
}

function timeoutBucketMs(value: unknown): number | undefined {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
    return undefined;
  }
  if (value === 0) return 0;
  return TIMEOUT_BUCKETS_MS.find((boundary) => value <= boundary);
}

function measuredDurationMs(value: unknown): number | undefined {
  if (
    typeof value !== "number" ||
    !Number.isFinite(value) ||
    value < 0 ||
    value > MAX_DURATION_MS
  ) {
    return undefined;
  }
  return Math.round(value);
}

function sumDuration(total: number, value: unknown): number | undefined {
  const candidate = measuredDurationMs(value);
  if (candidate === undefined || total + candidate > MAX_DURATION_MS) {
    return undefined;
  }
  return total + candidate;
}

function provider(value: unknown): z.infer<typeof Provider> | undefined {
  if (typeof value !== "string" || value.length === 0 || value.length > 128) {
    return undefined;
  }
  const normalized = value.toLowerCase();
  const category = normalized.split(/[.:/]/u, 1)[0]?.replace(/_/gu, "-");
  if (category === "azure" || category === "azure-openai") {
    return "azure_openai";
  }
  if (category === "bedrock" || category === "amazon-bedrock") {
    return "amazon_bedrock";
  }
  if (category === "vertex" || category === "vertex-ai") return "vertex";
  if (category === "anthropic") return "anthropic";
  if (category === "openai") return "openai";
  if (category === "google") return "google";
  if (category === "mistral") return "mistral";
  if (category === "cohere") return "cohere";
  if (category === "xai") return "xai";
  if (category === "groq") return "groq";
  if (category === "deepseek") return "deepseek";
  if (category === "perplexity") return "perplexity";
  if (category === "together") return "together";
  if (category === "fireworks") return "fireworks";
  if (category === "cerebras") return "cerebras";
  if (category === "replicate") return "replicate";
  if (category === "huggingface") return "huggingface";
  if (category === "gateway") return "gateway";
  return "other";
}

function modelFamily(value: unknown): z.infer<typeof ModelFamily> | undefined {
  if (typeof value !== "string" || value.length === 0 || value.length > 128) {
    return undefined;
  }
  const normalized = value.toLowerCase();
  if (/^gpt-5(?:$|[-.:/])/u.test(normalized)) return "gpt-5";
  if (/^gpt-4\.1(?:$|[-.:/])/u.test(normalized)) return "gpt-4.1";
  if (/^gpt-4o(?:$|[-.:/])/u.test(normalized)) return "gpt-4o";
  if (/^o[134](?:$|[-.:/])/u.test(normalized)) return "o-series";
  if (
    /^claude(?:$|[-.:/])/u.test(normalized) &&
    /(?:^|-)opus(?:-|$)/u.test(normalized)
  ) {
    return "claude-opus";
  }
  if (
    /^claude(?:$|[-.:/])/u.test(normalized) &&
    /(?:^|-)sonnet(?:-|$)/u.test(normalized)
  ) {
    return "claude-sonnet";
  }
  if (
    /^claude(?:$|[-.:/])/u.test(normalized) &&
    /(?:^|-)haiku(?:-|$)/u.test(normalized)
  ) {
    return "claude-haiku";
  }
  if (/^gemini(?:$|[-.:/])/u.test(normalized)) return "gemini";
  if (/^llama(?:$|[-.:/])/u.test(normalized)) return "llama";
  if (/^(?:mistral|mixtral)(?:$|[-.:/])/u.test(normalized)) {
    return "mistral";
  }
  if (/^command(?:$|[-.:/])/u.test(normalized)) return "command";
  if (/^grok(?:$|[-.:/])/u.test(normalized)) return "grok";
  if (/^deepseek(?:$|[-.:/])/u.test(normalized)) return "deepseek";
  if (/^qwen(?:$|[-.:/])/u.test(normalized)) return "qwen";
  if (/^(?:text-)?embedding(?:$|[-.:/])/u.test(normalized)) return "embedding";
  if (/^rerank(?:$|[-.:/])/u.test(normalized)) return "rerank";
  return "other";
}

function outputKind(
  value: unknown,
  currentOperation: z.infer<typeof Operation>,
): z.infer<typeof OutputKind> | undefined {
  const name = property(value, "name");
  const parsed = OutputKind.safeParse(name);
  if (parsed.success) return parsed.data;
  return currentOperation === "generate_text" ||
    currentOperation === "stream_text"
    ? "text"
    : undefined;
}

function objectKeyCount(value: unknown): number | undefined {
  const candidate = record(value);
  if (!candidate) return undefined;
  try {
    let total = 0;
    for (const key in candidate) {
      if (!Object.prototype.hasOwnProperty.call(candidate, key)) continue;
      total += 1;
      if (total > MAX_SCAN_ITEMS) return undefined;
    }
    return total;
  } catch {
    return undefined;
  }
}

function reasoningEffort(
  value: unknown,
): z.infer<typeof ReasoningEffort> | undefined {
  const parsed = ReasoningEffort.safeParse(value);
  return parsed.success ? parsed.data : undefined;
}

function operation(value: unknown): z.infer<typeof Operation> {
  switch (value) {
    case "ai.generateText":
      return "generate_text";
    case "ai.generateObject":
      return "generate_object";
    case "ai.embed":
      return "embed";
    case "ai.embedMany":
      return "embed_many";
    case "ai.rerank":
      return "rerank";
    case "ai.streamText":
    case "ai.streamObject":
      return "other";
    default:
      return "other";
  }
}

function finishReason(
  value: unknown,
): z.infer<typeof FinishReason> | undefined {
  const unified =
    typeof value === "string" ? value : property(value, "unified");
  switch (unified) {
    case "stop":
    case "length":
    case "error":
    case "other":
      return unified;
    case "content-filter":
      return "content_filter";
    case "tool-calls":
      return "tool_calls";
    default:
      return undefined;
  }
}

function optionalCount(
  key: string,
  value: unknown,
  max = MAX_TOKEN_COUNT,
): JsonRecord {
  const candidate = count(value, max);
  return candidate === undefined ? {} : { [key]: candidate };
}

function optionalIntegerBucket(
  key: string,
  value: unknown,
  boundaries: readonly number[],
): JsonRecord {
  const candidate = positiveIntegerBucket(value, boundaries);
  return candidate === undefined ? {} : { [key]: candidate };
}

function optionalDecimal(
  key: string,
  value: unknown,
  minimum: number,
  maximum: number,
): JsonRecord {
  const candidate = boundedDecimal(value, minimum, maximum);
  return candidate === undefined ? {} : { [key]: candidate };
}

function optionalTimeout(key: string, value: unknown): JsonRecord {
  const candidate = timeoutBucketMs(value);
  return candidate === undefined ? {} : { [key]: candidate };
}

function performanceTotals(steps: unknown): {
  providerResponseMs?: number;
  stepTimeMs?: number;
  toolExecutionMs?: number;
} {
  let length: number;
  try {
    if (!Array.isArray(steps)) return {};
    length = steps.length;
  } catch {
    return {};
  }
  if (length > MAX_SCAN_ITEMS) return {};

  let providerResponseMs = 0;
  let stepTimeMs = 0;
  let toolExecutionMs = 0;
  let hasProviderResponse = false;
  let hasStepTime = false;
  let hasToolExecution = false;
  let scannedToolTimings = 0;

  for (let index = 0; index < length; index += 1) {
    const performance = property(property(steps, String(index)), "performance");
    const response = measuredDurationMs(
      property(performance, "responseTimeMs"),
    );
    if (response !== undefined) {
      const next = sumDuration(providerResponseMs, response);
      if (next === undefined) return {};
      providerResponseMs = next;
      hasProviderResponse = true;
    }
    const step = measuredDurationMs(property(performance, "stepTimeMs"));
    if (step !== undefined) {
      const next = sumDuration(stepTimeMs, step);
      if (next === undefined) return {};
      stepTimeMs = next;
      hasStepTime = true;
    }
    const timings = record(property(performance, "toolExecutionMs"));
    if (!timings) continue;
    try {
      for (const key in timings) {
        if (!Object.prototype.hasOwnProperty.call(timings, key)) continue;
        scannedToolTimings += 1;
        if (scannedToolTimings > MAX_SCAN_ITEMS) return {};
        const next = sumDuration(toolExecutionMs, property(timings, key));
        if (next === undefined) return {};
        toolExecutionMs = next;
        hasToolExecution = true;
      }
    } catch {
      return {};
    }
  }

  return {
    ...(hasProviderResponse ? { providerResponseMs } : {}),
    ...(hasStepTime ? { stepTimeMs } : {}),
    ...(hasToolExecution || length > 0 ? { toolExecutionMs } : {}),
  };
}

function endProjection(value: unknown): JsonRecord {
  const usage = property(value, "usage");
  const inputTokens =
    count(property(usage, "inputTokens")) ?? count(property(usage, "tokens"));
  const outputTokens = count(property(usage, "outputTokens"));
  const totalTokens = count(property(usage, "totalTokens"));
  const inputTokenDetails = property(usage, "inputTokenDetails");
  const outputTokenDetails = property(usage, "outputTokenDetails");
  const steps = property(value, "steps");
  const toolCalls = property(value, "toolCalls");
  const embedding = property(value, "embedding");
  const ranking = property(value, "ranking");
  const reason = finishReason(property(value, "finishReason"));
  const { providerResponseMs, stepTimeMs, toolExecutionMs } =
    performanceTotals(steps);
  const warningCount = arrayLength(property(value, "warnings"));
  const toolResultCount = arrayLength(property(value, "toolResults"));
  const contentPartCount = arrayLength(property(value, "content"));
  const fileCount = arrayLength(property(value, "files"));
  const sourceCount = arrayLength(property(value, "sources"));
  const responseMessageCount = arrayLength(property(value, "responseMessages"));
  const modelCallCount = arrayLength(steps);
  const embeddingLength = arrayLength(embedding);
  const firstEmbeddingIsArray =
    embeddingLength === undefined || embeddingLength === 0
      ? undefined
      : isArray(property(embedding, "0"));

  return {
    ...(reason ? { finish_reason: reason } : {}),
    ...optionalCount("input_tokens", inputTokens),
    ...optionalCount("output_tokens", outputTokens),
    ...optionalCount(
      "total_tokens",
      totalTokens ??
        (inputTokens !== undefined && outputTokens !== undefined
          ? count(inputTokens + outputTokens)
          : undefined),
    ),
    ...optionalCount(
      "cached_input_tokens",
      property(inputTokenDetails, "cacheReadTokens"),
    ),
    ...optionalCount(
      "cache_write_input_tokens",
      property(inputTokenDetails, "cacheWriteTokens"),
    ),
    ...optionalCount("text_tokens", property(outputTokenDetails, "textTokens")),
    ...optionalCount(
      "reasoning_tokens",
      property(outputTokenDetails, "reasoningTokens"),
    ),
    ...(modelCallCount === undefined
      ? {}
      : { model_call_count: modelCallCount }),
    ...(modelCallCount === undefined ? {} : { step_count: modelCallCount }),
    ...(arrayLength(toolCalls) === undefined
      ? {}
      : { tool_call_count: arrayLength(toolCalls) }),
    ...(toolResultCount === undefined
      ? {}
      : { tool_result_count: toolResultCount }),
    ...(warningCount === undefined ? {} : { warning_count: warningCount }),
    ...(contentPartCount === undefined
      ? {}
      : { content_part_count: contentPartCount }),
    ...(fileCount === undefined ? {} : { file_count: fileCount }),
    ...(sourceCount === undefined ? {} : { source_count: sourceCount }),
    ...(responseMessageCount === undefined
      ? {}
      : { response_message_count: responseMessageCount }),
    ...(providerResponseMs === undefined
      ? {}
      : { provider_response_ms: providerResponseMs }),
    ...(stepTimeMs === undefined ? {} : { step_time_ms: stepTimeMs }),
    ...(toolExecutionMs === undefined
      ? {}
      : { tool_execution_ms: toolExecutionMs }),
    ...(embeddingLength === undefined
      ? {}
      : embeddingLength === 0
        ? { result_count: 0 }
        : firstEmbeddingIsArray === true
          ? { result_count: embeddingLength }
          : firstEmbeddingIsArray === false
            ? { result_count: 1 }
            : {}),
    ...(arrayLength(ranking) === undefined
      ? {}
      : { result_count: arrayLength(ranking) }),
  };
}

export const AiSdkPlugin = plugin({
  id: "ai-sdk",
  events: { operations: AiOperation },
  instrument({ events, begin }) {
    const start = (
      value: unknown,
      currentOperation: z.infer<typeof Operation>,
    ) => {
      const inputValue = property(value, "value");
      const documents = property(value, "documents");
      const model = property(value, "model");
      const output = property(value, "output");
      const tools = property(value, "tools");
      const timeout = property(value, "timeout");
      const timeoutOptions = record(timeout);
      const effort = reasoningEffort(property(value, "reasoning"));
      const stopSequences = property(value, "stopSequences");
      const currentProvider = provider(
        property(value, "provider") ?? property(model, "provider"),
      );
      const currentModelFamily = modelFamily(
        property(value, "modelId") ?? property(model, "modelId"),
      );
      const currentOutputKind = outputKind(output, currentOperation);
      const currentToolCount =
        objectKeyCount(tools) ?? (tools === undefined ? 0 : undefined);
      const stopSequenceCount = arrayLength(stopSequences);
      const itemCount =
        currentOperation === "embed"
          ? 1
          : currentOperation === "embed_many"
            ? arrayLength(inputValue)
            : currentOperation === "rerank"
              ? arrayLength(documents)
              : undefined;
      return begin(
        events.operations,
        {
          operation: currentOperation,
          ...(currentProvider ? { provider: currentProvider } : {}),
          ...(currentModelFamily ? { model_family: currentModelFamily } : {}),
          ...optionalCount(
            "max_retries",
            property(value, "maxRetries"),
            MAX_RETRIES,
          ),
          ...optionalIntegerBucket(
            "max_output_tokens",
            property(value, "maxOutputTokens"),
            OUTPUT_TOKEN_BUCKETS,
          ),
          ...optionalDecimal(
            "temperature",
            property(value, "temperature"),
            0,
            2,
          ),
          ...optionalDecimal("top_p", property(value, "topP"), 0, 1),
          ...optionalIntegerBucket(
            "top_k",
            property(value, "topK"),
            TOP_K_BUCKETS,
          ),
          ...optionalDecimal(
            "presence_penalty",
            property(value, "presencePenalty"),
            -2,
            2,
          ),
          ...optionalDecimal(
            "frequency_penalty",
            property(value, "frequencyPenalty"),
            -2,
            2,
          ),
          ...(typeof property(value, "seed") === "number" &&
          Number.isSafeInteger(property(value, "seed"))
            ? { seeded: true }
            : {}),
          ...(effort ? { reasoning_effort: effort } : {}),
          ...(stopSequenceCount === undefined
            ? {}
            : { stop_sequence_count: stopSequenceCount }),
          ...(currentOutputKind ? { output_kind: currentOutputKind } : {}),
          ...(currentToolCount === undefined
            ? {}
            : { tool_count: currentToolCount }),
          ...optionalTimeout(
            "timeout_ms",
            typeof timeout === "number"
              ? timeout
              : property(timeoutOptions, "totalMs"),
          ),
          ...optionalTimeout(
            "step_timeout_ms",
            property(timeoutOptions, "stepMs"),
          ),
          ...optionalTimeout(
            "chunk_timeout_ms",
            property(timeoutOptions, "chunkMs"),
          ),
          ...optionalTimeout(
            "tool_timeout_ms",
            property(timeoutOptions, "toolMs"),
          ),
          ...(itemCount === undefined ? {} : { item_count: itemCount }),
          ...optionalCount(
            "requested_result_count",
            property(value, "topN"),
            MAX_AGGREGATE_COUNT,
          ),
        },
        { retainParent: true },
      );
    };
    type Handle = ReturnType<typeof start>;
    const active = new Map<
      string,
      { handle: Handle; timeout: ReturnType<typeof setTimeout> }
    >();

    const take = (value: unknown): Handle | undefined => {
      const id = callId(value);
      if (!id) return;
      const entry = active.get(id);
      if (!entry) return;
      active.delete(id);
      clearTimeout(entry.timeout);
      return entry.handle;
    };

    const integration: Telemetry = {
      onStart(value) {
        const id = callId(value);
        if (!id) return;
        const currentOperation = operation(property(value, "operationId"));
        if (currentOperation === "other") return;
        const previous = active.get(id);
        if (previous) return;
        while (!active.has(id) && active.size >= 1_024) {
          const oldestId = active.keys().next().value as string | undefined;
          if (!oldestId) break;
          const oldest = active.get(oldestId);
          active.delete(oldestId);
          if (oldest) {
            clearTimeout(oldest.timeout);
            oldest.handle.cancel("ai_overflow");
          }
        }
        const handle = start(value, currentOperation);
        const timeout = setTimeout(() => {
          active.delete(id);
          handle.cancel("ai_timeout");
        }, 5 * 60_000);
        timeout.unref?.();
        active.set(id, { handle, timeout });
      },
      onEnd(value) {
        const handle = take(value);
        if (!handle) return;
        const projected = endProjection(value);
        handle.end(projected, {
          success: projected.finish_reason !== "error",
        });
      },
      onAbort(value) {
        take(value)?.cancel("ai_aborted");
      },
      onError(value) {
        take(value)?.fail(property(value, "error"));
      },
    };

    type StreamTextFunction = typeof streamText;
    type Instrumenter = (() => Telemetry) & {
      streamText<F extends StreamTextFunction>(implementation: F): F;
    };
    const streamTextWrappers = new WeakMap<
      StreamTextFunction,
      StreamTextFunction
    >();
    const createAiSdkTelemetry = (() => integration) as Instrumenter;
    createAiSdkTelemetry.streamText = <F extends StreamTextFunction>(
      implementation: F,
    ): F => {
      const existingWrapper = streamTextWrappers.get(implementation);
      if (existingWrapper) return existingWrapper as F;
      const wrapped = function (this: unknown, ...args: unknown[]): unknown {
        const supplied = record(args[0]);
        if (!supplied) {
          return Reflect.apply(
            implementation as (...values: unknown[]) => unknown,
            this,
            args,
          );
        }
        const telemetry =
          record(property(supplied, "telemetry")) ??
          record(property(supplied, "experimental_telemetry"));
        const configuredIntegrations = property(telemetry, "integrations");
        const selectedIntegrations =
          configuredIntegrations === undefined
            ? undefined
            : Array.isArray(configuredIntegrations)
              ? configuredIntegrations
              : [configuredIntegrations];
        if (
          property(telemetry, "isEnabled") === false ||
          (selectedIntegrations !== undefined &&
            !selectedIntegrations.includes(integration))
        ) {
          return Reflect.apply(
            implementation as (...values: unknown[]) => unknown,
            this,
            args,
          );
        }
        const handle = start(supplied, "stream_text");
        const existingEnd =
          typeof supplied.onEnd === "function"
            ? supplied.onEnd
            : typeof supplied.onFinish === "function"
              ? supplied.onFinish
              : undefined;
        const existingAbort =
          typeof supplied.onAbort === "function" ? supplied.onAbort : undefined;
        const existingError =
          typeof supplied.onError === "function" ? supplied.onError : undefined;
        const invoke = (callback: unknown, value: unknown): unknown =>
          Reflect.apply(
            callback as (...values: unknown[]) => unknown,
            undefined,
            [value],
          );
        const options = {
          ...supplied,
          onEnd: async (value: unknown) => {
            try {
              const result = existingEnd
                ? await invoke(existingEnd, value)
                : undefined;
              const projected = endProjection(value);
              handle.end(projected, {
                success: projected.finish_reason !== "error",
              });
              return result;
            } catch (error) {
              handle.fail(error);
              throw error;
            }
          },
          onAbort: async (value: unknown) => {
            try {
              const result = existingAbort
                ? await invoke(existingAbort, value)
                : undefined;
              handle.cancel("ai_aborted");
              return result;
            } catch (error) {
              handle.fail(error);
              throw error;
            }
          },
          onError: async (value: unknown) => {
            try {
              const result = existingError
                ? await invoke(existingError, value)
                : console.error(property(value, "error"));
              handle.fail(property(value, "error"));
              return result;
            } catch (error) {
              handle.fail(error);
              throw error;
            }
          },
        };
        try {
          return Reflect.apply(
            implementation as (...values: unknown[]) => unknown,
            this,
            [options, ...args.slice(1)],
          );
        } catch (error) {
          handle.fail(error);
          throw error;
        }
      };
      const typedWrapper = wrapped as F;
      streamTextWrappers.set(implementation, typedWrapper);
      streamTextWrappers.set(typedWrapper, typedWrapper);
      return typedWrapper;
    };
    return createAiSdkTelemetry;
  },
});

import { event } from "@useamplio/amplio";
import { plugin } from "@useamplio/amplio/plugin";
import type { CreateEmailOptions, Resend } from "resend";
import { z } from "zod";

const ResendSend = event({
  id: "resend.send",
  version: 1,
  schema: z.object({
    provider: z.literal("resend"),
    template: z.string().optional(),
  }),
  timing: "duration",
  cardinality: { many: { max: 16 } },
});

const templateTag = (input: CreateEmailOptions): string | undefined =>
  input.tags?.find((tag) => tag.name === "template")?.value;

const instrumentedClients = new WeakSet<Resend>();

export const ResendPlugin = plugin({
  id: "resend",
  events: { sends: ResendSend },
  instrument({ events, observe }) {
    return <Client extends Resend>(client: Client): Client => {
      if (instrumentedClients.has(client)) {
        return client;
      }

      const send = client.emails.send.bind(client.emails);
      client.emails.send = observe(events.sends, send, {
        input: ({ args: [input] }) => {
          const template = templateTag(input);
          return {
            provider: "resend",
            ...(template ? { template } : {}),
          };
        },
        success: ({ result }) => result.error === null,
      });
      instrumentedClients.add(client);
      return client;
    };
  },
});

import { init } from "@useamplio/amplio";
import { consoleSink } from "./sinks/console.js";

init({
  service: process.env.SERVICE_NAME ?? "my-app",
  env: process.env.NODE_ENV ?? "development",
  enrichers: [],
  // sampling: { rate: 0.1, keep: [{ field: "success", equals: false }] },
  // see @useamplio/amplio README ## Sampling
  sinks: [consoleSink],
});

import type { Sink } from "@useamplio/amplio";

const createJsonReplacer = () => {
  const ancestors: object[] = [];
  return function (this: object, _key: string, value: unknown): unknown {
    if (typeof value === "bigint") {
      return value.toString();
    }
    if (value === null || typeof value !== "object") {
      return value;
    }
    while (ancestors.length > 0 && ancestors[ancestors.length - 1] !== this) {
      ancestors.pop();
    }
    if (ancestors.includes(value)) {
      return "[Circular]";
    }
    ancestors.push(value);
    return value;
  };
};

export const consoleSink: Sink = (record) => {
  console.log(JSON.stringify(record, createJsonReplacer()));
};

/**
 * Dev-grade JSONL sink — appendFileSync blocks the event loop.
 * Use sink-otlp for production. Path from AMPLIO_JSON_SINK_PATH env or option;
 * defaults to amplio.<env>.jsonl (e.g. amplio.development.jsonl) so dev rows
 * and build/production rows never interleave in one file. Add amplio*.jsonl
 * to .gitignore (amplio add sink json does this).
 */
import fs from "node:fs";
import path from "node:path";
import type { Sink, SinkRecord } from "@useamplio/amplio";

export interface JsonFileSinkOptions {
  path?: string;
}

export function jsonFileSink(options: JsonFileSinkOptions = {}): Sink {
  const explicitPath =
    options.path ?? (process.env.AMPLIO_JSON_SINK_PATH?.trim() || undefined);

  return (record: SinkRecord) => {
    const env = typeof record.env === "string" && record.env ? record.env : "dev";
    const filePath = explicitPath ?? `amplio.${env}.jsonl`;
    const dir = path.dirname(filePath);
    if (dir && dir !== ".") {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.appendFileSync(filePath, `${JSON.stringify(record)}\n`, "utf8");
  };
}

/**
 * OTLP/HTTP logs sink.
 *
 * Endpoint resolution (first match wins):
 *   1. options.endpoint                          — `/v1/logs` appended unless already present
 *   2. OTEL_EXPORTER_OTLP_LOGS_ENDPOINT          — used VERBATIM (per the OTel spec,
 *      signal-specific endpoints are full URLs)
 *   3. OTEL_EXPORTER_OTLP_ENDPOINT               — base URL, `/v1/logs` appended
 *
 * Delivery: by default this sink POSTs ONE request per emit — fine for dev
 * and low traffic, not for production request rates. Pass `batch: true`
 * (100 records / 1 s) or `batch: { maxSize, maxWaitMs }` to coalesce records
 * into one export request. Batching makes the sink async-pending between
 * flushes. Amplio's `flush()` calls the sink's active drain hook, so shutdown
 * and short-lived/serverless paths can deliver a partial batch immediately.
 */
import type { JsonValue, Sink, SinkRecord } from "@useamplio/amplio";

export interface OtlpSinkOptions {
  endpoint?: string;
  headers?: Record<string, string>;
  /** When false (default), export failures warn once then stay silent. Pass true to throw. */
  throwOnError?: boolean;
  /**
   * Record fields promoted to typed OTLP log attributes (the fields you can
   * filter on in an OTel backend without parsing the JSON body). Dot paths
   * walk nested objects (`"http.status"` → record.http.status). Replaces the
   * default list; the full record always ships in the log body.
   */
  attributes?: string[];
  /**
   * Coalesce records into one export request. `true` = 100 records / 1 s;
   * pass `{ maxSize, maxWaitMs }` to tune. Default: off (one POST per emit).
   */
  batch?: boolean | { maxSize?: number; maxWaitMs?: number };
}

const DEFAULT_ATTRIBUTE_FIELDS = [
  "service",
  "@event",
  "duration_ms",
  "request_id",
  "success",
  // The fields people actually filter on in an OTel backend:
  "http.method",
  "http.route",
  "http.status",
  "rpc.procedures",
] as const;

const DEFAULT_BATCH_MAX_SIZE = 100;
const DEFAULT_BATCH_MAX_WAIT_MS = 1_000;

type OtlpAttributeValue =
  | { stringValue: string }
  | { boolValue: boolean }
  | { intValue: string }
  | { doubleValue: number }
  | { arrayValue: { values: OtlpAttributeValue[] } }
  | { kvlistValue: { values: OtlpAttribute[] } };

interface OtlpAttribute {
  key: string;
  value: OtlpAttributeValue;
}

const parseOtlpHeaders = (raw: string | undefined): Record<string, string> => {
  if (!raw) {
    return {};
  }

  const headers: Record<string, string> = {};
  for (const pair of raw.split(",")) {
    const trimmed = pair.trim();
    if (!trimmed) {
      continue;
    }

    const eq = trimmed.indexOf("=");
    if (eq === -1) {
      continue;
    }

    const key = trimmed.slice(0, eq).trim();
    const value = trimmed.slice(eq + 1).trim();
    if (key) {
      headers[key] = value;
    }
  }

  return headers;
};

/** Flat key first (`record["http.status"]`), then dot-path walk (`record.http.status`). */
const fieldValue = (
  record: SinkRecord,
  field: string,
): JsonValue | undefined => {
  if (field === "@event") {
    return record["@event"];
  }
  const flat = record[field];
  if (flat !== undefined || !field.includes(".")) {
    return flat;
  }
  let current: JsonValue | undefined = record as JsonValue;
  for (const part of field.split(".")) {
    if (
      current === null ||
      typeof current !== "object" ||
      Array.isArray(current)
    ) {
      return undefined;
    }
    current = (current as Record<string, JsonValue>)[part];
  }
  return current;
};

const toOtlpValue = (
  value: JsonValue | undefined,
): OtlpAttributeValue | undefined => {
  if (value === null || value === undefined) {
    return undefined;
  }

  if (typeof value === "string") {
    return { stringValue: value };
  }

  if (typeof value === "boolean") {
    return { boolValue: value };
  }

  if (typeof value === "number") {
    if (Number.isInteger(value)) {
      return { intValue: String(value) };
    }
    return { doubleValue: value };
  }

  if (Array.isArray(value)) {
    const values = value
      .map((item) => toOtlpValue(item))
      .filter((item): item is OtlpAttributeValue => item !== undefined);
    return { arrayValue: { values } };
  }

  const values = Object.entries(value)
    .map(([key, item]) => toOtlpAttribute(key, item))
    .filter((item): item is OtlpAttribute => item !== undefined);
  return { kvlistValue: { values } };
};

const toOtlpAttribute = (
  key: string,
  value: JsonValue | undefined,
): OtlpAttribute | undefined => {
  const converted = toOtlpValue(value);
  return converted ? { key, value: converted } : undefined;
};

const toTimeUnixNano = (timestamp: JsonValue | undefined): string => {
  let ms: number;

  if (typeof timestamp === "number" && Number.isFinite(timestamp)) {
    ms = timestamp;
  } else if (typeof timestamp === "string" && timestamp.length > 0) {
    const parsed = Date.parse(timestamp);
    ms = Number.isNaN(parsed) ? Date.now() : parsed;
  } else {
    ms = Date.now();
  }

  return `${Math.trunc(ms)}000000`;
};

const resolveUrl = (options: OtlpSinkOptions): string | undefined => {
  const appendLogsPath = (endpoint: string): string => {
    const base = endpoint.replace(/\/$/, "");
    return base.endsWith("/v1/logs") ? base : `${base}/v1/logs`;
  };

  if (options.endpoint) {
    return appendLogsPath(options.endpoint);
  }
  // Per the OTel spec the signal-specific endpoint is a full URL used as-is;
  // only the base endpoint gets the signal path appended.
  const signalEndpoint = process.env.OTEL_EXPORTER_OTLP_LOGS_ENDPOINT;
  if (signalEndpoint) {
    return signalEndpoint;
  }
  const baseEndpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT;
  if (baseEndpoint) {
    return appendLogsPath(baseEndpoint);
  }
  return undefined;
};

const resourceKeyOf = (record: SinkRecord): string => {
  const attributes = buildResourceAttributes(record).sort((left, right) =>
    left.key.localeCompare(right.key),
  );
  return JSON.stringify(attributes);
};

const buildResourceAttributes = (record: SinkRecord): OtlpAttribute[] => {
  const attributes: OtlpAttribute[] = [];
  const keys = new Set<string>();
  const add = (attribute: OtlpAttribute | undefined): void => {
    if (!attribute || keys.has(attribute.key)) return;
    keys.add(attribute.key);
    attributes.push(attribute);
  };

  if (typeof record.service === "string" && record.service.length > 0) {
    add({ key: "service.name", value: { stringValue: record.service } });
  }
  if (typeof record.env === "string" && record.env.length > 0) {
    add({
      key: "deployment.environment",
      value: { stringValue: record.env },
    });
  }

  const resource = record.resource;
  if (
    resource !== null &&
    typeof resource === "object" &&
    !Array.isArray(resource)
  ) {
    for (const [key, value] of Object.entries(resource)) {
      add(toOtlpAttribute(key, value));
    }
  }

  return attributes;
};

export function otlpSink(options: OtlpSinkOptions = {}): Sink {
  const url = resolveUrl(options);
  const throwOnError = options.throwOnError ?? false;
  const attributeFields = options.attributes ?? DEFAULT_ATTRIBUTE_FIELDS;
  const headers = {
    "content-type": "application/json",
    ...parseOtlpHeaders(process.env.OTEL_EXPORTER_OTLP_HEADERS),
    ...(options.headers ?? {}),
  };

  if (!url) {
    let warned = false;
    return async () => {
      if (!warned) {
        warned = true;
        console.warn(
          "[amplio] otlpSink: no endpoint configured — set OTEL_EXPORTER_OTLP_LOGS_ENDPOINT (full URL, used verbatim) or OTEL_EXPORTER_OTLP_ENDPOINT (base URL, /v1/logs appended), or pass otlpSink({ endpoint }); OTLP export is disabled",
        );
      }
    };
  }

  let warnedExportFailure = false;

  const warnExportFailure = (detail: string): void => {
    if (throwOnError || warnedExportFailure) {
      return;
    }
    warnedExportFailure = true;
    console.warn(
      `[amplio] otlpSink: export failed (${detail}); further failures will be silent. Pass throwOnError: true to fail hard.`,
    );
  };

  const buildAttributes = (record: SinkRecord): OtlpAttribute[] => {
    const attributes: OtlpAttribute[] = [];
    for (const field of attributeFields) {
      // Keep the conventional OTLP attribute key `event` while sourcing the
      // canonical semantic `@event` field by default.
      const key = field === "@event" ? "event" : field;
      const attr = toOtlpAttribute(key, fieldValue(record, field));
      if (attr) {
        attributes.push(attr);
      }
    }
    return attributes;
  };

  const toLogRecord = (record: SinkRecord) => {
    const attributes = buildAttributes(record);
    return {
      timeUnixNano: toTimeUnixNano(record.timestamp),
      body: { stringValue: JSON.stringify(record) },
      ...(attributes.length > 0 ? { attributes } : {}),
    };
  };

  // One resourceLogs entry per distinct OTLP resource — records in a batch
  // usually share one, but never stamp record A with B's resource attributes.
  const buildPayload = (records: SinkRecord[]) => {
    const groups = new Map<string, SinkRecord[]>();
    for (const record of records) {
      const key = resourceKeyOf(record);
      const group = groups.get(key);
      if (group) {
        group.push(record);
      } else {
        groups.set(key, [record]);
      }
    }

    const resourceLogs = [...groups.values()].map((group) => {
      const first = group[0]!;
      const resourceAttributes = buildResourceAttributes(first);
      return {
        ...(resourceAttributes.length > 0
          ? { resource: { attributes: resourceAttributes } }
          : {}),
        scopeLogs: [{ logRecords: group.map(toLogRecord) }],
      };
    });

    return { resourceLogs };
  };

  const exportRecords = async (records: SinkRecord[]): Promise<void> => {
    let response: Response;
    try {
      response = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(buildPayload(records)),
      });
    } catch (error) {
      if (throwOnError) {
        throw error;
      }
      warnExportFailure("network_error");
      return;
    }

    if (!response.ok) {
      if (throwOnError) {
        throw new Error(`OTLP export failed with status ${response.status}`);
      }
      warnExportFailure(`status ${response.status}`);
      return;
    }
  };

  if (!options.batch) {
    return (record: SinkRecord) => exportRecords([record]);
  }

  const batchConfig = options.batch === true ? {} : options.batch;
  const maxSize = batchConfig.maxSize ?? DEFAULT_BATCH_MAX_SIZE;
  const maxWaitMs = batchConfig.maxWaitMs ?? DEFAULT_BATCH_MAX_WAIT_MS;

  let buffer: SinkRecord[] = [];
  let timer: ReturnType<typeof setTimeout> | null = null;
  let pending: {
    promise: Promise<void>;
    resolve: () => void;
    reject: (e: unknown) => void;
  } | null = null;

  const flushBatch = (): Promise<void> => {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    const records = buffer;
    const settled = pending;
    buffer = [];
    pending = null;
    if (records.length === 0) {
      settled?.resolve();
      return Promise.resolve();
    }
    const delivery = exportRecords(records).then(
      () => settled?.resolve(),
      (error) => {
        // Every emit in the batch awaited this promise — reject them all so
        // throwOnError surfaces per-record, matching the unbatched contract.
        if (settled) {
          settled.reject(error);
        }
      },
    );
    return delivery;
  };

  const sink: Sink = (record: SinkRecord): Promise<void> => {
    buffer.push(record);
    if (pending === null) {
      let resolve!: () => void;
      let reject!: (e: unknown) => void;
      const promise = new Promise<void>((res, rej) => {
        resolve = res;
        reject = rej;
      });
      pending = { promise, resolve, reject };
    }
    const result = pending.promise;
    if (buffer.length >= maxSize) {
      void flushBatch();
    } else if (timer === null) {
      timer = setTimeout(flushBatch, maxWaitMs);
      // Don't keep a Node process alive just for a pending batch window.
      (timer as { unref?: () => void }).unref?.();
    }
    return result;
  };
  sink.flush = flushBatch;
  return sink;
}

type ResourceAttributes = Readonly<Record<string, string | number | boolean>>;
type ResourceEnricher = (
  current: ResourceAttributes,
) => ResourceAttributes | undefined;

function envOrUndefined(key: string): string | undefined {
  const value = process.env[key]?.trim();
  return value ? value : undefined;
}

/** Adds bounded operational attributes under `record.resource`. */
export const serviceMetadata: ResourceEnricher = (
  current: ResourceAttributes,
) => ({
  ...current,
  ...(envOrUndefined("AMPLIO_SERVICE")
    ? { "deployment.name": envOrUndefined("AMPLIO_SERVICE")! }
    : {}),
  ...(envOrUndefined("AMPLIO_SERVICE_VERSION")
    ? { "deployment.version": envOrUndefined("AMPLIO_SERVICE_VERSION")! }
    : {}),
  ...(envOrUndefined("AMPLIO_REGION")
    ? { "deployment.region": envOrUndefined("AMPLIO_REGION")! }
    : {}),
});
